  "promos": [
    {
      "title": "Burn the Weed, Hang the Witch",
      "start_block": "B017",
      "end_block": "B049",
      "hook": "The Elder Nobleman lunges forward and thrusts his gold-handled cane against Rupert's chest, pinning him to the wall as he snarls, \"Then make certain she isn't! A peasant weed, Rupert! You do not store weeds in your cellar, you burn them!\"",
      "cliffhanger": "The Elder Nobleman commands, \"Drag her before the magistrate tomorrow, frame the trial, buy the jury, and let the State hang her,\" and the scene cuts before anyone reacts to the full weight of the death sentence.",
      "why": "It opens with physical intimidation and a venomous threat, then escalates into a cold, calculated conspiracy to execute Juliana, ending on the unresolved horror of the plan being set in motion.",
      "context_gap": "A stranger may not know Juliana is the imprisoned healer they are plotting to kill, but the stakes are clear from the dialogue."
    },
    {
      "title": "She Will Hang",
      "start_block": "B054",
      "end_block": "B067",
      "hook": "Catherine leans forward and asks, \"And the Dowager?\" as the Elder Nobleman dismisses the dying woman's testimony, making clear they will silence every obstacle.",
      "cliffhanger": "The Elder Nobleman's face fills the frame as he declares, \"Tomorrow, she stops being a prisoner. She becomes a witch,\" and the screen cuts before Juliana's fate is sealed.",
      "why": "It builds from dismissive cruelty toward the poisoned Dowager to Catherine's exultant \"She will hang,\" ending on a chilling declaration that reframes Juliana's identity as a condemned witch.",
      "context_gap": "A stranger may not know the Dowager is Alexander's mother or that Juliana is innocent, but the conspirators' malice is unmistakable."
    },
    {
      "title": "The Witch in the Cellar",
      "start_block": "B007",
      "end_block": "B031",
      "hook": "The Elder Nobleman coldly tells Rupert, \"You have a rat in your cellar, Rupert. And the servants are beginning to smell it,\" immediately establishing a hidden prisoner and a spreading secret.",
      "cliffhanger": "The Elder Nobleman declares, \"We use the law to destroy her,\" and the scene cuts before he explains how they will turn the law into a weapon.",
      "why": "It hooks with a sinister accusation about a hidden prisoner, builds paranoia as Rupert fears Juliana will speak, and ends on the unresolved promise of legal destruction.",
      "context_gap": "A stranger may not know who the 'rat' is or why she is imprisoned, but the threat and secrecy are instantly gripping."
    }
  ],
  "moments": [
    {
      "start_block": "B017",
      "end_block": "B019",
      "kind": "hook",
      "description": "The Elder Nobleman pins Rupert against the wall with his cane and snarls, \"You do not store weeds in your cellar, you burn them!\""
    },
    {
      "start_block": "B043",
      "end_block": "B047",
      "kind": "reveal",
      "description": "The Elder Nobleman says, \"Then call it witchcraft,\" and when Rupert protests it is a capital charge, he replies with unflinching finality, \"Precisely.\""
    },
    {
      "start_block": "B062",
      "end_block": "B063",
      "kind": "cliffhanger",
      "description": "Catherine beams with venomous glee and declares, \"She will hang. A perfect solution. The town will cheer as the witch's disgraced daughter faces the noose.\""
    },
    {
      "start_block": "B066",
      "end_block": "B067",
      "kind": "cliffhanger",
      "description": "The Elder Nobleman's cold, predatory eyes fill the frame as he declares, \"Tomorrow, she stops being a prisoner. She becomes a witch.\""
    }
  ]
}
